// FILE: src/tasks/auto-archive-stale.js
// Archives candidates who have gone quiet: no stage movement for the company's
// configured number of days, on a posting that is still open. Run directly:
//
//   node src/tasks/auto-archive-stale.js
//
// OPT-IN, PER COMPANY. A company with autoArchiveStaleDays unset (the default) is
// skipped entirely — silently rejecting people is not a default anyone should get.
//
// NO EMAIL IS SENT. This is cleanup of a list, not a decision about a person, and
// a rejection letter generated by a timer is worse than no letter at all. The
// human archive path (applicant-archive-service) still emails; this one never does.
//
// IDEMPOTENT BY CONSTRUCTION. The query requires archived:null, so a second run the
// same day matches nothing the first run touched. There is no cursor or run marker:
// running it twice, or never, converges on the same state.

import { col, closeDb } from '../Db/connection.js';
import { findOrCreateArchiveReasonForCompany } from '../models/employer/archive-reason-model.js';

const ARCHIVE_REASON_TEXT = 'No response';
export const MIN_STALE_DAYS = 7;
export const MAX_STALE_DAYS = 90;

/** Clamp a company's configured threshold; null/invalid means "disabled". */
export function resolveStaleDays(value) {
  if (!Number.isFinite(value)) return null;
  const days = Math.round(value);
  if (days < MIN_STALE_DAYS || days > MAX_STALE_DAYS) return null;
  return days;
}

/** Application ids in the set that have an interview scheduled in the future. */
async function applicationIdsWithFutureInterviews(companyOid, applicationIds, now) {
  if (applicationIds.length === 0) return new Set();
  const interviews = await col('interviews');
  const booked = await interviews.find({
    companyId: companyOid,
    applicationId: { $in: applicationIds },
    status: 'scheduled',
    startAtUtc: { $gt: now },
  }).project({ applicationId: 1 }).toArray();
  return new Set(booked.map((doc) => doc.applicationId?.toString()).filter(Boolean));
}

/** Archive one company's stale candidates. Returns { archived, postings }. */
export async function autoArchiveStaleForCompany(company, now = new Date()) {
  const days = resolveStaleDays(company.autoArchiveStaleDays);
  if (days === null) return { archived: 0, postings: 0 };

  const cutoff = new Date(now.getTime() - days * 86400000);
  const companyOid = company._id;

  // Only postings still taking candidates. Archiving against a closed posting is
  // the posting-close flow's job, not this one's.
  const activePostings = await (await col('jobs'))
    .find({ companyId: companyOid, source: 'native', status: 'active' })
    .project({ _id: 1 })
    .toArray();
  if (activePostings.length === 0) return { archived: 0, postings: 0 };

  const applications = await col('applications');
  const stale = await applications.find({
    companyId: companyOid,
    jobId: { $in: activePostings.map((posting) => posting._id) },
    archived: null,
    lastStageMovedAt: { $lt: cutoff },
  }).project({ _id: 1, jobId: 1, stageId: 1 }).toArray();
  if (stale.length === 0) return { archived: 0, postings: 0 };

  // A booked interview is an active conversation, whatever the stage timestamp says.
  const withInterviews = await applicationIdsWithFutureInterviews(
    companyOid, stale.map((doc) => doc._id), now,
  );
  const targets = stale.filter((doc) => !withInterviews.has(doc._id.toString()));
  if (targets.length === 0) return { archived: 0, postings: 0 };

  const reason = await findOrCreateArchiveReasonForCompany(companyOid, ARCHIVE_REASON_TEXT);
  await applications.updateMany(
    { _id: { $in: targets.map((doc) => doc._id) }, companyId: companyOid, archived: null },
    { $set: { archived: { at: now, reasonId: reason._id, note: 'Auto-archived after inactivity' }, updatedAt: now } },
  );

  // The timeline must show what happened, exactly as a human archive does.
  await (await col('stage_changes')).insertMany(targets.map((doc) => ({
    applicationId: doc._id,
    fromStageId: doc.stageId ?? null,
    toStageId: doc.stageId ?? null,
    movedByUserId: null,
    movedAt: now,
    note: `Archived: ${ARCHIVE_REASON_TEXT}`,
  })));

  return {
    archived: targets.length,
    postings: new Set(targets.map((doc) => doc.jobId?.toString())).size,
  };
}

/** Run for every company that has opted in. Returns the totals. */
export async function autoArchiveStale(now = new Date()) {
  const companies = await (await col('companies'))
    .find({ autoArchiveStaleDays: { $gte: MIN_STALE_DAYS } })
    .project({ _id: 1, name: 1, autoArchiveStaleDays: 1 })
    .toArray();

  let archived = 0;
  let postings = 0;
  for (const company of companies) {
    const result = await autoArchiveStaleForCompany(company, now);
    archived += result.archived;
    postings += result.postings;
  }

  console.log(`[auto-archive] Auto-archived ${archived} stale candidates across ${postings} postings`);
  return { archived, postings, companies: companies.length };
}

/** Only on direct execution, so a test or scheduler can import the function alone. */
const isDirectRun = process.argv[1] && process.argv[1].endsWith('auto-archive-stale.js');
if (isDirectRun) {
  autoArchiveStale()
    .then(async () => {
      await closeDb();
      process.exit(0);
    })
    .catch(async (err) => {
      console.error(`[auto-archive] failed: ${err.message}`);
      await closeDb().catch(() => {});
      process.exit(1);
    });
}
